const dataCleaningSnippets = [{"title":"Inspect dataset quality","why":"shape, info(), describe() மூலம் dataset structure மற்றும் suspicious values-ஐ முதலில் பாருங்கள்.","code":"import pandas as pd\n\ndf = pd.DataFrame({\n    'Machine': ['M01', 'M02', 'M01', None, 'M03'],\n    'Shift': ['Morning', 'Night', 'Morning', 'Evening', 'Night'],\n    'Target': [1400, 1400, 1400, 1400, 1400],\n    'Actual': [1350, 1200, 1350, 1100, 1500],\n    'Defects': [12, 18, 12, None, 9]\n})\nprint('Shape:', df.shape)\ndf.info()\ndisplay(df.describe(include='all'))"},{"title":"Find missing values","why":"isna().sum() ஒவ்வொரு column-ல் எத்தனை missing values உள்ளன எனக் காட்டும்.","code":"print(df.isna().sum())\nprint('Missing percentage:')\nprint((df.isna().mean() * 100).round(2))"},{"title":"Remove duplicate rows","why":"duplicated() duplicate rows-ஐ கண்டறியும்; drop_duplicates() repeated rows-ஐ நீக்கும். முதலில் எத்தனை duplicate என்று சரிபார்க்கவும்.","code":"print('Duplicate rows:', df.duplicated().sum())\ndf = df.drop_duplicates()\nprint('After removing duplicates:', df.shape)"},{"title":"Handle missing values","why":"Numeric columns-க்கு median/mean, categorical columns-க்கு mode அல்லது 'Unknown' பயன்படுத்தலாம். Strategy business context-ஐப் பொறுத்தது.","code":"df['Machine'] = df['Machine'].fillna('Unknown')\ndf['Defects'] = df['Defects'].fillna(df['Defects'].median())\nprint(df.isna().sum())\ndisplay(df)"},{"title":"Fix incorrect data types","why":"to_numeric() numeric conversion-க்கும் to_datetime() date conversion-க்கும் பயன்படும். errors='coerce' தவறான values-ஐ NaN ஆக்கும்.","code":"df['Actual'] = pd.to_numeric(df['Actual'], errors='coerce')\ndf['Defects'] = pd.to_numeric(df['Defects'], errors='coerce')\nprint(df.dtypes)"},{"title":"Detect outliers with IQR","why":"IQR = Q3 - Q1. IQR bounds-க்கு வெளியே உள்ள values potential outliers; context இல்லாமல் delete செய்யக்கூடாது.","code":"q1 = df['Actual'].quantile(0.25)\nq3 = df['Actual'].quantile(0.75)\niqr = q3 - q1\nlower = q1 - 1.5 * iqr\nupper = q3 + 1.5 * iqr\noutliers = df[(df['Actual'] < lower) | (df['Actual'] > upper)]\nprint('IQR limits:', lower, upper)\ndisplay(outliers)"},{"title":"Validate business rules","why":"Production columns-க்கு domain rules அமைத்து invalid records-ஐ கண்டுபிடிக்கவும்.","code":"invalid = df[(df['Actual'] < 0) | (df['Defects'] < 0) | (df['Defects'] > df['Actual'])]\nprint('Invalid production records:', len(invalid))\ndisplay(invalid)"},{"title":"Complete data cleaning workflow","why":"Raw data-வை clean செய்து, missing values, duplicates மற்றும் invalid records அனைத்தையும் மீண்டும் validate செய்யுங்கள்.","code":"clean = df.copy()\nclean = clean.drop_duplicates()\nclean['Machine'] = clean['Machine'].fillna('Unknown')\nclean['Defects'] = clean['Defects'].fillna(clean['Defects'].median())\nclean = clean[(clean['Actual'] >= 0) & (clean['Defects'] >= 0) & (clean['Defects'] <= clean['Actual'])]\nprint('Final shape:', clean.shape)\nprint('Missing values:\\n', clean.isna().sum())\nprint('Duplicates:', clean.duplicated().sum())\ndisplay(clean)"}];


const preprocessingSnippets = [
 {title:'Create a mixed-type production dataset',why:'Numerical மற்றும் categorical columns-ஐ அடையாளம் காண்பது preprocessing-ன் முதல் படி.',code:"import pandas as pd\n\ndf = pd.DataFrame({'Machine':['M01','M02','M01','M03','M02','M03'], 'Shift':['Morning','Night','Evening','Morning','Night','Evening'], 'Material':['Cotton','Polyester','Cotton','Nylon','Polyester','Cotton'], 'Production':[1200,1500,1100,1350,1600,1250], 'Defects':[12,8,20,10,7,15]})\ndisplay(df)\nprint(df.dtypes)"},
 {title:'Separate numerical and categorical features',why:'Numerical columns-க்கு scaling-மும் categorical columns-க்கு encoding-மும் தேவைப்படலாம்.',code:"numeric_cols = df.select_dtypes(include='number').columns.tolist()\ncategorical_cols = df.select_dtypes(include='object').columns.tolist()\nprint('Numeric:', numeric_cols)\nprint('Categorical:', categorical_cols)"},
 {title:'One-Hot Encoding',why:'Machine, Shift போன்ற nominal categories-க்கு artificial order உருவாக்காமல் indicator columns உருவாக்கும்.',code:"encoded = pd.get_dummies(df, columns=['Machine','Shift','Material'], dtype=int)\ndisplay(encoded.head())"},
 {title:'StandardScaler and MinMaxScaler',why:'StandardScaler values-ஐ mean 0 / standard deviation 1 அளவிற்கு மாற்றும். MinMaxScaler பொதுவாக 0–1 range தரும்.',code:"from sklearn.preprocessing import StandardScaler, MinMaxScaler\nvalues = df[['Production','Defects']]\nprint('StandardScaler:\\n', StandardScaler().fit_transform(values))\nprint('MinMaxScaler:\\n', MinMaxScaler().fit_transform(values))"},
 {title:'Train-test split',why:'Model train data-ல் கற்றுக்கொண்டு unseen test data-ல் மதிப்பிட வேண்டும். Test data-ஐ training-க்கு பயன்படுத்தாதீர்கள்.',code:"from sklearn.model_selection import train_test_split\nX = df[['Production','Defects']]\ny = (df['Production'] >= 1300).astype(int)\nX_train, X_test, y_train, y_test = train_test_split(X, y, test_size=0.25, random_state=42, stratify=y)\nprint(X_train.shape, X_test.shape)"},
 {title:'Prevent data leakage with Pipeline',why:'Scaler-ஐ முழு dataset-ல் fit செய்தால் test data தகவல் train-க்கு கசியலாம். Pipeline-ல் fit training data-க்கு மட்டும் நடக்கும்.',code:"from sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LogisticRegression\nmodel = make_pipeline(StandardScaler(), LogisticRegression())\nmodel.fit(X_train, y_train)\nprint('Test accuracy:', model.score(X_test, y_test))"},
 {title:'Imputation inside a Pipeline',why:'Missing values-ஐ நிரப்பும் median போன்ற statistics-ஐ training split-ல் மட்டும் கற்றுக்கொள்ள SimpleImputer பயன்படும்.',code:"from sklearn.impute import SimpleImputer\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.linear_model import LogisticRegression\npipe = make_pipeline(SimpleImputer(strategy='median'), StandardScaler(), LogisticRegression())\npipe.fit(X_train, y_train)\nprint('Test score:', pipe.score(X_test, y_test))"}
];

