const advancedModules = {"4":{"intro":"EDA என்பது dataset-ன் structure, distributions, relationships, patterns மற்றும் anomalies-ஐ model training-க்கு முன் ஆராயும் process.","why":"Production-ல் எந்த machine/shift-ல் defects அதிகம், target miss எங்கு, production-defect தொடர்பு உள்ளதா என்பதைக் கண்டறிய உதவும்.","workflow":["shape, info, describe மூலம் dataset inspect செய்","Univariate distributions மற்றும் category counts பாரு","Bivariate relationships-ஐ scatter/boxplot மூலம் ஆராய்","Correlation heatmap மூலம் multivariate pattern பாரு","Missing values/outliers மீண்டும் சரிபார்","Evidence-based insights பதிவு செய்"],"snippets":[["Load and inspect a real dataset","Seaborn sample tips dataset பயன்படுத்தி shape, columns மற்றும் statistics பார்க்கலாம்.","import seaborn as sns\\ndf=sns.load_dataset('tips')\\nprint(df.shape, df.columns.tolist())\\ndisplay(df.describe(include='all'))"],["Univariate distribution","ஒரு numeric feature distribution-ஐ histogram மூலம் பாருங்கள்.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=sns.load_dataset('tips')\\nsns.histplot(data=df,x='total_bill',kde=True)\\nplt.show()"],["Bivariate analysis","Bill மற்றும் tip இடையிலான relationship-ஐ hue grouping உடன் பாருங்கள்.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=sns.load_dataset('tips')\\nsns.scatterplot(data=df,x='total_bill',y='tip',hue='time')\\nplt.show()"],["Correlation heatmap","Numeric features இடையிலான correlation-ஐ பாருங்கள்; correlation causation அல்ல.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=sns.load_dataset('tips')\\nsns.heatmap(df.select_dtypes('number').corr(),annot=True)\\nplt.show()"],["Production machine summary","Machine அடிப்படையில் average output மற்றும் defect rate கணக்கிடுங்கள்.","import pandas as pd\\ndf=pd.DataFrame({'Machine':['M01','M02','M01','M03'],'Actual':[1200,1100,1350,1400],'Defects':[12,30,15,8]})\\ng=df.groupby('Machine').sum(numeric_only=True)\\ng['defect_rate_pct']=g.Defects/g.Actual*100\\ndisplay(g)"]],"exercises":["Load a dataset and report rows, columns, types","Plot one numeric distribution and explain it","Compare numeric values across categories using boxplot","Create and interpret a correlation heatmap","Find machine with highest defect rate","Write three evidence-based insights without claiming causation"],"quiz":[["EDA-ன் நோக்கம்?","Model deploy|Data patterns மற்றும் quality புரிதல்|API உருவாக்கம்|Backup",1,"EDA data structure, distribution மற்றும் relationships ஆராய்கிறது."],["Numeric distribution chart?","Histogram|Pie only|Table header|Network graph",0,"Histogram frequency distribution காட்டும்."],["Correlation 0.9 என்றால்?","Causation proved|Strong positive association|No missing data|Equal values",1,"Correlation association; causation அல்ல."],["Category-wise spread compare?","Boxplot|Word cloud|SQL join|File list",0,"Boxplot median, quartiles, spread காட்டும்."],["Multivariate analysis?","One variable|Several variables relationships|Delete row|Rename file",1,"பல variables ஒன்றாக ஆய்வு செய்யப்படுகின்றன."]],"projectTitle":"Elastic Production EDA Report","projectCode":"import pandas as pd\\nimport seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=pd.DataFrame({'Machine':['M01','M02','M01','M03','M02','M03'],'Shift':['Day','Night','Night','Day','Day','Night'],'Target':[1400]*6,'Actual':[1200,1100,1350,1400,1250,900],'Defects':[12,30,15,8,22,40]})\\ndf['achievement_pct']=df.Actual/df.Target*100\\ndf['defect_rate_pct']=df.Defects/df.Actual*100\\nprint(df.groupby('Machine')[['Actual','Defects','achievement_pct','defect_rate_pct']].mean())\\nsns.boxplot(data=df,x='Machine',y='defect_rate_pct'); plt.show()"},"5":{"intro":"Matplotlib என்பது static charts உருவாக்கும் foundational Python visualization library.","why":"Daily output trend, machine comparison, defect distribution மற்றும் target achievement report உருவாக்க பயன்படும்.","workflow":["Business question வரையறு","x/y variables தேர்வு செய்","Line, bar, scatter, histogram, boxplot தேர்வு செய்","Title, labels, units, legend சேர்க்கவும்","Chart-ஐ interpret செய்து PNG export செய்"],"snippets":[["Line chart","Time series trend மற்றும் target line பார்க்கலாம்.","import matplotlib.pyplot as plt\\ndays=['Mon','Tue','Wed','Thu','Fri']\\nactual=[1200,1350,1100,1450,1500]\\nplt.plot(days,actual,marker='o',label='Actual')\\nplt.axhline(1400,ls='--',label='Target')\\nplt.legend(); plt.xlabel('Day'); plt.ylabel('Pieces'); plt.show()"],["Bar chart","Machine-wise average production compare செய்யலாம்.","import matplotlib.pyplot as plt\\nplt.bar(['M01','M02','M03'],[1320,1180,1450])\\nplt.title('Average Production by Machine'); plt.ylabel('Pieces'); plt.show()"],["Scatter plot","Production மற்றும் defects association பார்க்கலாம்.","import matplotlib.pyplot as plt\\nplt.scatter([900,1100,1200,1300,1400,1500],[40,30,22,18,12,10])\\nplt.xlabel('Production'); plt.ylabel('Defects'); plt.show()"],["Histogram and boxplot","Distribution மற்றும் potential outliers ஆய்வு செய்யலாம்.","import matplotlib.pyplot as plt\\nvalues=[900,1100,1150,1200,1250,1300,1350,1400,1450,2100]\\nfig,ax=plt.subplots(1,2)\\nax[0].hist(values,bins=5); ax[1].boxplot(values)\\nplt.show()"],["Subplots and save","பல charts-ஐ ஒரே report-ல் save செய்யலாம்.","import matplotlib.pyplot as plt\\nfig,ax=plt.subplots(1,2)\\nax[0].plot([1,2,3],[100,120,140]); ax[1].bar(['M1','M2'],[12,8])\\nplt.tight_layout(); plt.savefig('report.png'); plt.show()"]],"exercises":["Line chart with daily output and target","Bar chart comparing three machines","Scatter plot Actual vs Defects and explain pattern","Histogram and boxplot of production","Two-panel chart and export PNG","Add units, labels, title and legend"],"quiz":[["Time trend chart?","Line chart|Pie|Boxplot|Heatmap",0,"Line chart time order trend காட்டும்."],["Category comparison?","Bar chart|Histogram|Scatter only|KDE",0,"Bar chart categories compare செய்கிறது."],["Histogram shows?","Numeric distribution|Database schema|Text labels|Model weights",0,"Histogram numeric frequency distribution."],["plt.xlabel()?","x-axis label|Delete chart|Sort data|Fit model",0,"xlabel x-axis label அமைக்கிறது."],["Save figure method?","plt.savefig()|save_csv()|fit_html()|to_model()",0,"savefig figure file export செய்கிறது."]],"projectTitle":"Production Performance Chart Pack","projectCode":"import matplotlib.pyplot as plt\\nimport pandas as pd\\ndf=pd.DataFrame({'Day':['Mon','Tue','Wed','Thu','Fri'],'Target':[1400]*5,'Actual':[1200,1350,1100,1450,1500],'Defects':[12,18,25,10,8]})\\nfig,ax=plt.subplots(2,2,figsize=(9,6))\\nax[0,0].plot(df.Day,df.Actual); ax[0,0].axhline(1400,ls='--')\\nax[0,1].bar(df.Day,df.Defects); ax[1,0].hist(df.Actual); ax[1,1].scatter(df.Actual,df.Defects)\\nplt.tight_layout(); plt.savefig('production_charts.png'); plt.show()"},"6":{"intro":"Seaborn என்பது Matplotlib அடிப்படையிலான statistical visualization library; distribution, category comparison, relationship மற்றும் heatmap charts எளிதாக உருவாக்கும்.","why":"Shift-wise defects, machine output spread, material quality மற்றும் feature correlations ஆராய உதவும்.","workflow":["DataFrame load செய்","x/y/hue variables தேர்வு செய்","Distribution, categorical அல்லது relational plot தேர்வு செய்","Labels மற்றும் theme அமை","Pattern-ஐ business context-ல் verify செய்"],"snippets":[["Theme and histogram","Theme அமைத்து distribution பார்க்கலாம்.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\nsns.set_theme(style='whitegrid')\\ndf=sns.load_dataset('tips')\\nsns.histplot(data=df,x='total_bill',kde=True); plt.show()"],["Bar and count plots","Category-wise mean மற்றும் frequency ஒப்பிடலாம்.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=sns.load_dataset('tips')\\nsns.barplot(data=df,x='day',y='total_bill',hue='sex'); plt.show()\\nsns.countplot(data=df,x='day'); plt.show()"],["Boxplot and violin","Spread, quartiles மற்றும் density ஒப்பிடலாம்.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=sns.load_dataset('tips')\\nsns.boxplot(data=df,x='day',y='total_bill'); plt.show()\\nsns.violinplot(data=df,x='day',y='tip'); plt.show()"],["Pairplot","பல numeric feature pairs பார்க்கலாம்.","import seaborn as sns\\ndf=sns.load_dataset('iris')\\nsns.pairplot(df,hue='species',corner=True)"],["Correlation heatmap","Numeric correlation matrix-ஐ colour-coded view-ல் பார்க்கலாம்.","import seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=sns.load_dataset('penguins').dropna()\\nsns.heatmap(df.select_dtypes('number').corr(),annot=True,cmap='vlag'); plt.show()"]],"exercises":["Use histplot with KDE","Compare categories using barplot and hue","Use boxplot for shift-wise production spread","Pairplot Iris with species hue","Create correlation heatmap","Write one insight and one limitation"],"quiz":[["Seaborn built on?","Matplotlib|TensorFlow|Flask|Express",0,"Seaborn Matplotlib-ஐ அடிப்படையாகக் கொண்டது."],["hue parameter?","Colour grouping|Fill missing|Delete rows|Save chart",0,"hue categorical colour grouping செய்கிறது."],["Heatmap visualises?","Correlation matrix|Text tokens|Model deployment|Passwords",0,"Heatmap matrix values colour மூலம் காட்டும்."],["Pairplot purpose?","Pairwise numeric relationships|Only sum|File conversion|Model fit",0,"Pairplot numeric pair relationships காட்டும்."],["Violin plot shows?","Density distribution|Only sum|Missing count|SQL joins",0,"Violin distribution density-ஐக் காட்டும்."]],"projectTitle":"Shift-wise Quality Visualization","projectCode":"import pandas as pd\\nimport seaborn as sns\\nimport matplotlib.pyplot as plt\\ndf=pd.DataFrame({'Machine':['M01','M02','M01','M03','M02','M03'],'Shift':['Day','Night','Night','Day','Day','Night'],'Actual':[1200,1100,1350,1400,1250,900],'Defects':[12,30,15,8,22,40]})\\ndf['defect_rate']=df.Defects/df.Actual*100\\nfig,ax=plt.subplots(1,2,figsize=(9,4))\\nsns.boxplot(data=df,x='Shift',y='defect_rate',ax=ax[0]); sns.barplot(data=df,x='Machine',y='Actual',hue='Shift',ax=ax[1]); plt.show()"},"7":{"intro":"Plotly என்பது hover, zoom, pan, legend toggle மற்றும் HTML export ஆதரவுள்ள interactive visualization library.","why":"Production dashboard-ல் machine/shift details hover செய்து inspect செய்து share செய்யலாம்.","workflow":["Plotly Express அல்லது Graph Objects தேர்வு செய்","DataFrame மற்றும் x/y/color fields கொடு","Title, labels, hover_data அமை","Interactive chart inspect செய்","HTML export செய்து browser-ல் திற"],"snippets":[["Interactive line chart","Actual vs target trend hover மற்றும் zoom உடன்.","import pandas as pd\\nimport plotly.express as px\\ndf=pd.DataFrame({'Day':['Mon','Tue','Wed','Thu'],'Actual':[1200,1350,1100,1450],'Target':[1400]*4})\\npx.line(df,x='Day',y=['Actual','Target'],markers=True).show()"],["Interactive bar chart","Machine comparison-ல் hover data சேர்க்கலாம்.","import pandas as pd\\nimport plotly.express as px\\ndf=pd.DataFrame({'Machine':['M01','M02','M03'],'Actual':[4200,3900,4500],'Defects':[35,52,27]})\\npx.bar(df,x='Machine',y='Actual',color='Machine',hover_data=['Defects']).show()"],["Scatter with hover","Machine and shift grouping உடன் relationship பார்க்கலாம்.","import pandas as pd\\nimport plotly.express as px\\ndf=pd.DataFrame({'Machine':['M01','M02','M03'],'Actual':[1200,1100,1400],'Defects':[12,30,8],'Shift':['Day','Night','Day']})\\npx.scatter(df,x='Actual',y='Defects',color='Machine',symbol='Shift',hover_data=['Shift']).show()"],["Interactive histogram","Numeric distribution bins மாற்றி பார்க்கலாம்.","import pandas as pd\\nimport plotly.express as px\\ndf=pd.DataFrame({'Actual':[900,1100,1150,1200,1250,1300,1350,1400,1450,1500]})\\npx.histogram(df,x='Actual',nbins=6).show()"],["Dashboard and HTML export","பல interactive charts-ஐ HTML-ஆக export செய்யலாம்.","import pandas as pd\\nimport plotly.express as px\\ndf=pd.DataFrame({'Machine':['M01','M02','M03'],'Actual':[4200,3900,4500],'Defects':[35,52,27]})\\nfig=px.bar(df,x='Machine',y='Actual',color='Machine',hover_data=['Defects'])\\nfig.write_html('production_dashboard.html'); fig.show()"]],"exercises":["Interactive line chart actual vs target","Bar chart with hover details","Scatter coloured by machine and symbol by shift","Histogram with different bin count","Export interactive chart as HTML","Explain when interactive chart beats static chart"],"quiz":[["Plotly key feature?","Interactive hover/zoom|Only printed text|CSV only|SQL",0,"Plotly interactive browser charts தருகிறது."],["Plotly Express?","High-level chart API|Password hashing|Missing value fill|Database",0,"Plotly Express குறைந்த code-ல் charts உருவாக்கும்."],["HTML export method?","write_html()|save_csv()|to_model()|fit_html()",0,"Figure.write_html HTML export செய்கிறது."],["hover_data?","Tooltip extra fields|Delete chart|Train model|Shuffle rows",0,"hover_data tooltip fields காட்டும்."],["Zoom/pan are?","Interactive controls|Data cleaning|Encoding|Scaling",0,"Plotly toolbar interaction controls."]],"projectTitle":"Interactive Elastic Production Dashboard","projectCode":"import pandas as pd\\nimport plotly.express as px\\ndf=pd.DataFrame({'Day':['Mon','Tue','Wed','Thu','Fri'],'Machine':['M01','M02','M01','M03','M02'],'Target':[1400]*5,'Actual':[1200,1100,1350,1400,1250],'Defects':[12,30,15,8,22]})\\ndf['achievement_pct']=df.Actual/df.Target*100\\ndf['defect_rate']=df.Defects/df.Actual*100\\npx.line(df,x='Day',y=['Actual','Target'],markers=True).show()\\nfig=px.scatter(df,x='Actual',y='defect_rate',color='Machine',hover_data=['Day']); fig.write_html('elastic_dashboard.html'); fig.show()"},"8":{"intro":"Feature Engineering என்பது raw columns-லிருந்து model-க்கு பயனுள்ள புதிய features உருவாக்குதல், transform செய்தல் மற்றும் select செய்தல்.","why":"Production data-வில் date-லிருந்து weekday, target/actual-லிருந்து achievement மற்றும் shortage, defects/actual-லிருந்து defect rate உருவாக்கலாம்.","workflow":["Prediction target/time வரையறு","Business-meaningful derived features உருவாக்கு","Categorical/numeric transformations செய்","Target leakage மற்றும் future fields நீக்கு","Training split-ல் feature selection fit செய்","Validation மூலம் feature value சரிபார்"],"snippets":[["Date-based features","Datetime-லிருந்து weekday/month/weekend flags உருவாக்கலாம்.","import pandas as pd\\ndf=pd.DataFrame({'Date':pd.to_datetime(['2026-10-01','2026-10-02','2026-10-03'])})\\ndf['weekday']=df.Date.dt.dayofweek; df['month']=df.Date.dt.month; df['weekend']=(df.weekday>=5).astype(int); display(df)"],["Production KPI features","Achievement, shortage, defect rate போன்ற features உருவாக்கு.","import pandas as pd\\ndf=pd.DataFrame({'Target':[1400,1400,1400],'Actual':[1200,1500,1100],'Defects':[12,10,20]})\\ndf['achievement_pct']=df.Actual/df.Target*100\\ndf['shortage']=(df.Target-df.Actual).clip(lower=0)\\ndf['defect_rate_pct']=df.Defects/df.Actual*100; display(df)"],["Log transform","Highly skewed positive values-க்கு log1p பயன்படுத்தலாம்.","import numpy as np\\nimport pandas as pd\\ndf=pd.DataFrame({'downtime':[0,5,10,120,240,600]})\\ndf['log_downtime']=np.log1p(df.downtime); display(df)"],["Feature selection on train only","SelectKBest training data-ல் fit செய்து test-க்கு transform மட்டும் செய்.","from sklearn.datasets import load_breast_cancer\\nfrom sklearn.model_selection import train_test_split\\nfrom sklearn.feature_selection import SelectKBest, mutual_info_classif\\nX,y=load_breast_cancer(return_X_y=True,as_frame=True)\\nXtr,Xte,ytr,yte=train_test_split(X,y,test_size=.2,random_state=42,stratify=y)\\nsel=SelectKBest(mutual_info_classif,k=5).fit(Xtr,ytr)\\nprint(X.columns[sel.get_support()].tolist())"],["Interaction features","Business context அடிப்படையில் feature interaction உருவாக்கு.","import pandas as pd\\ndf=pd.DataFrame({'Speed':[80,90,100],'Runtime':[8,7,6],'Actual':[1200,1300,1400]})\\ndf['speed_runtime']=df.Speed*df.Runtime\\ndf['output_per_hour']=df.Actual/df.Runtime; display(df)"]],"exercises":["Extract weekday/month from date","Create achievement, shortage and defect-rate features","Compare raw and log1p distributions","Create one meaningful interaction feature","Use SelectKBest on training split","Identify a potential leakage feature and explain"],"quiz":[["Feature Engineering?","Create useful input features|Delete model|Backup|Change chart colour",0,"Raw data-ல் இருந்து useful features உருவாக்குகிறது."],["Date feature example?","Weekday|Password|API key|File path",0,"Datetime-ல் இருந்து weekday/month கிடைக்கும்."],["Target leakage?","Future/target info in features|Missing value|Duplicate index|Scaling",0,"Prediction நேரத்தில் கிடைக்காத தகவல் leakage."],["Shortage formula?","max(Target-Actual,0)|Target+Actual|Defects/Target|Actual*0",0,"Shortage non-negative ஆகக் கணக்கிடப்படுகிறது."],["Feature selection fit where?","Training data only|Test only|Full data before split|Production",0,"Test information leakage தவிர்க்க training மட்டும்."]],"projectTitle":"Production KPI Feature Engineering","projectCode":"import pandas as pd\\nimport numpy as np\\ndf=pd.DataFrame({'Date':pd.to_datetime(['2026-10-01','2026-10-02','2026-10-03','2026-10-04']),'Machine':['M01','M02','M01','M03'],'Target':[1400]*4,'Actual':[1200,1500,1100,1450],'Defects':[12,10,20,8],'Downtime':[30,5,120,10]})\\ndf['weekday']=df.Date.dt.dayofweek; df['achievement_pct']=df.Actual/df.Target*100; df['shortage']=(df.Target-df.Actual).clip(lower=0); df['defect_rate_pct']=df.Defects/df.Actual*100; df['log_downtime']=np.log1p(df.Downtime); display(df)"},"9":{"intro":"Advanced Data Analysis என்பது descriptive summaries-ஐத் தாண்டி hypothesis tests, confidence intervals, correlation, segmentation மற்றும் actionable insights உருவாக்கும் நிலை.","why":"Machine breakdown, shift மற்றும் defect patterns-ஐ sample variation கருத்தில் கொண்டு ஆய்வு செய்ய உதவும்.","workflow":["Business question மற்றும் H0/H1 அமை","Sample size, quality, assumptions சரிபார்","Group summaries மற்றும் confidence intervals கணக்கிடு","பொருத்தமான statistical test தேர்வு செய்","p-value, effect size, practical significance மதிப்பிடு","Limitations மற்றும் recommendation எழுதுக"],"snippets":[["Descriptive statistics by shift","Mean, median, std, sample size shift-wise ஒப்பிடு.","import pandas as pd\\ndf=pd.DataFrame({'Shift':['Day','Night','Day','Night','Evening'],'Defect_rate':[1.2,2.8,1.5,3.1,1.9]})\\ndisplay(df.groupby('Shift').Defect_rate.agg(['mean','median','std','count']))"],["Correlation and confidence interval","Pearson r association அளக்கும்; confidence interval mean uncertainty காட்டும்.","from scipy import stats\\nimport numpy as np\\na=[900,1000,1100,1200,1300,1400,1500]; b=[40,35,30,25,20,15,12]\\nprint(stats.pearsonr(a,b))\\nprint(stats.t.interval(.95,df=len(a)-1,loc=np.mean(a),scale=stats.sem(a)))"],["Welch independent t-test","Unequal variances அனுமதித்து இரண்டு independent group means compare செய்.","from scipy import stats\\nday=[1.2,1.5,1.4,1.1,1.6,1.3]; night=[2.1,2.4,1.9,2.5,2.2,2.0]\\nprint(stats.ttest_ind(day,night,equal_var=False))"],["Chi-square categorical test","Categorical variables independence-ஐ contingency table மூலம் test செய்.","import pandas as pd\\nfrom scipy.stats import chi2_contingency\\nt=pd.DataFrame([[30,10],[18,22]],index=['Day','Night'],columns=['Pass','Fail'])\\nprint(t); print(chi2_contingency(t))"],["Machine quality segmentation","Output மற்றும் defect rate இணைத்து machine segment உருவாக்கு.","import pandas as pd\\ndf=pd.DataFrame({'Machine':['M01','M01','M02','M02','M03','M03'],'Actual':[1400,1350,1100,1150,1500,1450],'Defects':[10,12,30,28,8,9]})\\ng=df.groupby('Machine').sum(numeric_only=True); g['rate']=g.Defects/g.Actual*100; g['segment']=g.rate.apply(lambda x:'High quality' if x<1 else 'Review'); display(g)"]],"exercises":["Summarise production and defect rate by shift","Calculate correlation and explain it is not causation","Run Welch t-test on independent shift samples","Run chi-square on categorical counts","Segment machines by output and defect rate","Write findings with sample limitations and recommendations"],"quiz":[["Null hypothesis?","No effect/difference baseline|Always large effect|100% accuracy|Clean data",0,"H0 baseline/no-effect statement."],["p-value meaning?","H0 probability|H0 கீழ் observed-or-more-extreme result probability|Effect size|Causation",1,"p-value null hypothesis assumptions கீழ் probability."],["Welch t-test?","Compare independent means with unequal variance|Encode categories|Resize image|Drop missing",0,"Welch test unequal variance அனுமதிக்கும்."],["Chi-square test?","Categorical counts|Continuous time only|Pixels|Embeddings",0,"Contingency table categorical counts பயன்படுத்தும்."],["Statistical vs practical significance?","Different concepts|Same|p-value alone enough|Sample size irrelevant",0,"Effect size மற்றும் business impact தனியாகப் பாருங்கள்."]],"projectTitle":"Machine and Shift Statistical Quality Audit","projectCode":"import pandas as pd\\nfrom scipy import stats\\ndf=pd.DataFrame({'Shift':['Day']*6+['Night']*6,'Defect_rate':[1.1,1.3,1.4,1.2,1.5,1.0,2.1,2.4,1.9,2.5,2.2,2.0]})\\nprint(df.groupby('Shift').Defect_rate.agg(['mean','median','std','count']))\\na=df[df.Shift=='Day'].Defect_rate; b=df[df.Shift=='Night'].Defect_rate\\nprint('Welch t-test:',stats.ttest_ind(a,b,equal_var=False))\\nprint('Interpret with effect size, assumptions and business context; sample is illustrative.')"},"10":{"intro":"Advanced ML Preprocessing என்பது ColumnTransformer, Pipeline, imbalanced data handling, cross-validation மற்றும் reproducible validation techniques.","why":"Defect prediction-ல் mixed types, missing values, rare categories மற்றும் class imbalance இருக்கும்; leakage-safe pipeline தேவை.","workflow":["Target distribution மற்றும் train/test split inspect செய்","Numeric/categorical transformers அமை","ColumnTransformer-ல் combine செய்","Pipeline-ல் preprocessing மற்றும் estimator இணை","Stratified cross-validation மற்றும் imbalance metrics பாரு","Untouched test set-ல் final evaluation செய்"],"snippets":[["ColumnTransformer","Numeric மற்றும் categorical columns-க்கு தனித்தனி transforms அமை.","from sklearn.compose import ColumnTransformer\\nfrom sklearn.preprocessing import OneHotEncoder,StandardScaler\\nfrom sklearn.impute import SimpleImputer\\nfrom sklearn.pipeline import Pipeline\\nnum=Pipeline([('impute',SimpleImputer(strategy='median')),('scale',StandardScaler())])\\ncat=Pipeline([('impute',SimpleImputer(strategy='most_frequent')),('ohe',OneHotEncoder(handle_unknown='ignore'))])\\nprep=ColumnTransformer([('num',num,['Production','Defects']),('cat',cat,['Machine','Shift'])]); print(prep)"],["End-to-end pipeline","Preprocessing + model ஒரே fit/predict workflow.","from sklearn.datasets import load_breast_cancer\\nfrom sklearn.model_selection import train_test_split\\nfrom sklearn.pipeline import make_pipeline\\nfrom sklearn.preprocessing import StandardScaler\\nfrom sklearn.linear_model import LogisticRegression\\nfrom sklearn.metrics import classification_report\\nX,y=load_breast_cancer(return_X_y=True); Xtr,Xte,ytr,yte=train_test_split(X,y,test_size=.2,random_state=42,stratify=y)\\np=make_pipeline(StandardScaler(),LogisticRegression(max_iter=2000)); p.fit(Xtr,ytr); print(classification_report(yte,p.predict(Xte)))"],["Stratified cross-validation","ஒவ்வொரு fold-லும் class proportions preserve செய்யும்.","from sklearn.model_selection import StratifiedKFold,cross_val_score\\nfrom sklearn.datasets import load_breast_cancer\\nfrom sklearn.pipeline import make_pipeline\\nfrom sklearn.preprocessing import StandardScaler\\nfrom sklearn.linear_model import LogisticRegression\\nX,y=load_breast_cancer(return_X_y=True); m=make_pipeline(StandardScaler(),LogisticRegression(max_iter=2000))\\ncv=StratifiedKFold(n_splits=5,shuffle=True,random_state=42); print(cross_val_score(m,X,y,cv=cv,scoring='f1'))"],["Imbalanced classification metrics","Accuracy மட்டும் அல்ல precision, recall, F1, PR-AUC பார்க்கவும்.","from sklearn.datasets import make_classification\\nfrom sklearn.model_selection import train_test_split\\nfrom sklearn.linear_model import LogisticRegression\\nfrom sklearn.metrics import classification_report,confusion_matrix,average_precision_score\\nX,y=make_classification(n_samples=1000,n_features=10,weights=[.92,.08],random_state=42); a,b,c,d=train_test_split(X,y,test_size=.25,stratify=y,random_state=42)\\nm=LogisticRegression(max_iter=1000).fit(a,c); pred=m.predict(b); print(confusion_matrix(d,pred)); print(classification_report(d,pred,zero_division=0)); print(average_precision_score(d,m.predict_proba(b)[:,1]))"],["Decision threshold","Validation set-ல் threshold business cost-க்கு ஏற்றவாறு தேர்வு செய்.","from sklearn.metrics import precision_recall_curve\\nproba=m.predict_proba(b)[:,1]\\np,r,t=precision_recall_curve(d,proba)\\nfor threshold in [.2,.3,.5,.7]: print(threshold,((proba>=threshold).sum()))"]],"exercises":["Build ColumnTransformer for mixed columns","Wrap preprocessing and estimator in Pipeline","Use StratifiedKFold and report mean F1","Evaluate imbalanced classes with precision/recall/F1/PR-AUC","Compare decision thresholds on validation data","Explain why test set stays untouched until final evaluation"],"quiz":[["ColumnTransformer?","Different transformers by columns|Sort rows|Animate chart|API",0,"ColumnTransformer column groups-க்கு transforms அமைக்கும்."],["StratifiedKFold preserves?","Class proportions|Column names|File size|Scale",0,"Fold-களில் class distribution பாதுகாக்க முயலும்."],["Imbalanced data metric?","Recall/F1|Accuracy only|Rows count|Training loss only",0,"Accuracy minority errors மறைக்கலாம்."],["Pipeline CV benefit?","Fit preprocessing inside each training fold|Test data train-க்கு சேர்க்கும்|Duplicate rows|Auto label",0,"Fold-specific fit leakage குறைக்கும்."],["Final test set use?","Final evaluation at end|Repeated tuning|Scaler fit|Feature selection",0,"Repeated test tuning estimate-ஐ optimistic ஆக்கும்."]],"projectTitle":"Production Defect Risk Classification Pipeline","projectCode":"import pandas as pd\\nfrom sklearn.model_selection import train_test_split,StratifiedKFold,cross_val_score\\nfrom sklearn.compose import ColumnTransformer\\nfrom sklearn.preprocessing import OneHotEncoder,StandardScaler\\nfrom sklearn.impute import SimpleImputer\\nfrom sklearn.pipeline import Pipeline\\nfrom sklearn.linear_model import LogisticRegression\\nfrom sklearn.metrics import classification_report,confusion_matrix\\ndf=pd.DataFrame({'Machine':['M01','M02','M01','M03','M02','M03','M01','M02','M03','M01','M02','M03'],'Shift':['Day','Night','Night','Day','Day','Night','Day','Night','Day','Night','Day','Night'],'Production':[1200,1100,1350,1400,1250,900,1450,1300,1550,1180,1420,1160],'Defects':[12,30,15,8,22,40,9,18,6,25,10,28]})\\ndf['high_defect']=(df.Defects/df.Production*100>=1.5).astype(int); X=df[['Machine','Shift','Production']]; y=df.high_defect\\nprep=ColumnTransformer([('num',Pipeline([('imp',SimpleImputer(strategy='median')),('scale',StandardScaler())]),['Production']),('cat',OneHotEncoder(handle_unknown='ignore'),['Machine','Shift'])])\\npipe=Pipeline([('prep',prep),('model',LogisticRegression(class_weight='balanced',max_iter=1000))])\\na,b,c,d=train_test_split(X,y,test_size=.25,random_state=42,stratify=y); cv=StratifiedKFold(n_splits=3,shuffle=True,random_state=42); print(cross_val_score(pipe,a,c,cv=cv,scoring='f1')); pipe.fit(a,c); print(confusion_matrix(d,pipe.predict(b))); print(classification_report(d,pipe.predict(b),zero_division=0))"},"11":{"intro":"End-to-End ML Projects என்பது business problem முதல் data preparation, EDA, feature engineering, training, evaluation, interpretation மற்றும் report வரை முழு workflow.","why":"Elastic quality prediction-ஐ reproducible notebook, metrics மற்றும் actionable recommendations உடன் portfolio project-ஆக உருவாக்கலாம்.","workflow":["Business problem, target, success metric define செய்","Dataset source மற்றும் data dictionary பதிவு செய்","Cleaning, EDA மற்றும் feature engineering செய்","Leakage-safe preprocessing pipeline அமை","Baseline மற்றும் candidate models compare செய்","Cross-validation மற்றும் final test evaluate செய்","Errors, limitations, recommendations report செய்"],"snippets":[["Project data and target definition","Problem, target, feature columns தெளிவாக அமைக்கவும்.","import pandas as pd\\ndf=pd.DataFrame({'Machine':['M01','M02','M03','M01','M02','M03','M01','M02'],'Shift':['Day','Night','Day','Night','Day','Night','Day','Night'],'Production':[1200,1100,1450,1300,1250,900,1500,1180],'Defects':[12,30,8,15,22,40,7,28]})\\ndf['high_defect']=(df.Defects/df.Production*100>=1.5).astype(int); X=df[['Machine','Shift','Production']]; y=df.high_defect; print(y.value_counts())"],["Baseline model","DummyClassifier baseline-ஐ meaningful reference-ஆகப் பயன்படுத்தவும்.","from sklearn.model_selection import train_test_split\\nfrom sklearn.dummy import DummyClassifier\\nfrom sklearn.metrics import classification_report\\nXtr,Xte,ytr,yte=train_test_split(X,y,test_size=.25,random_state=42,stratify=y)\\nbase=DummyClassifier(strategy='most_frequent').fit(Xtr,ytr); print(classification_report(yte,base.predict(Xte),zero_division=0))"],["Build complete pipeline","Preprocessing மற்றும் model ஒரே pipeline-ல்; test leakage தவிர்க்கவும்.","from sklearn.compose import ColumnTransformer\\nfrom sklearn.preprocessing import OneHotEncoder,StandardScaler\\nfrom sklearn.impute import SimpleImputer\\nfrom sklearn.pipeline import Pipeline\\nfrom sklearn.linear_model import LogisticRegression\\nprep=ColumnTransformer([('num',Pipeline([('imp',SimpleImputer(strategy='median')),('scale',StandardScaler())]),['Production']),('cat',OneHotEncoder(handle_unknown='ignore'),['Machine','Shift'])])\\nmodel=Pipeline([('prep',prep),('clf',LogisticRegression(max_iter=1000,class_weight='balanced'))]); model.fit(Xtr,ytr); print(model.score(Xte,yte))"],["Evaluate errors","Classification report மற்றும் confusion matrix-ல் false positive/negative inspect செய்.","from sklearn.metrics import classification_report,confusion_matrix,ConfusionMatrixDisplay\\nimport matplotlib.pyplot as plt\\npred=model.predict(Xte); print(classification_report(yte,pred,zero_division=0)); ConfusionMatrixDisplay.from_predictions(yte,pred); plt.show()"],["Export predictions","Predictions CSV மற்றும் reproducibility notes சேமிக்கவும்.","results=Xte.copy(); results['actual']=yte.values; results['predicted']=pred; results.to_csv('ml_project_predictions.csv',index=False); print('Saved ml_project_predictions.csv')"]],"exercises":["Write business problem, target and success metric","Create data dictionary for each feature","Complete cleaning, EDA and three charts","Build leakage-safe preprocessing/model pipeline","Compare Dummy baseline with a real model","Evaluate metrics and inspect false positives/negatives","Export predictions and write limitations/recommendations"],"quiz":[["End-to-end project first step?","Define problem and target|Tune immediately|Deploy API|Chart colours",0,"Problem and target guide workflow."],["Baseline model purpose?","Reference performance|Guarantee best|Replace cleaning|Avoid evaluation",0,"Baseline comparison reference."],["Minority class matters?","Recall/precision/F1|Accuracy only|Row count|Training loss",0,"Per-class metrics reveal minority performance."],["Reproducibility record?","Dataset, seed, preprocessing, metrics|Screenshot only|Model name only|Nothing",0,"These details allow repeatable analysis."],["Final report includes?","Results, limits, recommendations|Accuracy only|Code only|Marketing",0,"Responsible report includes findings and limitations."]],"projectTitle":"Capstone – Elastic Production Quality Prediction","projectCode":"import pandas as pd\\nfrom sklearn.model_selection import train_test_split\\nfrom sklearn.compose import ColumnTransformer\\nfrom sklearn.preprocessing import OneHotEncoder,StandardScaler\\nfrom sklearn.impute import SimpleImputer\\nfrom sklearn.pipeline import Pipeline\\nfrom sklearn.linear_model import LogisticRegression\\nfrom sklearn.metrics import classification_report,confusion_matrix\\ndf=pd.DataFrame({'Machine':['M01','M02','M03','M01','M02','M03','M01','M02','M03','M01','M02','M03'],'Shift':['Day','Night','Day','Night','Day','Night','Day','Night','Day','Night','Day','Night'],'Production':[1200,1100,1450,1300,1250,900,1500,1180,1550,1220,1420,1160],'Defects':[12,30,8,15,22,40,7,28,6,20,10,32]})\\ndf['rate']=df.Defects/df.Production*100; df['high_defect']=(df.rate>=1.5).astype(int); X=df[['Machine','Shift','Production']]; y=df.high_defect\\nprep=ColumnTransformer([('num',Pipeline([('imp',SimpleImputer(strategy='median')),('scale',StandardScaler())]),['Production']),('cat',OneHotEncoder(handle_unknown='ignore'),['Machine','Shift'])])\\npipe=Pipeline([('prep',prep),('model',LogisticRegression(class_weight='balanced',max_iter=1000))]); a,b,c,d=train_test_split(X,y,test_size=.25,random_state=42,stratify=y); pipe.fit(a,c); pred=pipe.predict(b); print(confusion_matrix(d,pred)); print(classification_report(d,pred,zero_division=0)); print('Use authorised real time-ordered production data and validate on a later period before operational use.')"}};

